export default function Card({ title, description, children, accent }) {
  return (
    <div className={`rounded-3xl border border-slate-800 bg-slate-900/80 p-6 shadow-2xl shadow-slate-950/20 ${accent || ''}`}>
      <div className="mb-4 flex items-center justify-between gap-4">
        <h3 className="text-lg font-semibold text-slate-100">{title}</h3>
      </div>
      <p className="mb-6 text-sm leading-6 text-slate-400">{description}</p>
      {children}
    </div>
  );
}
